python3 -c "import json, sys, subprocess

data = json.load(sys.stdin)
f = data.get('tool_input', {}).get('file_path', '')
if not f.endswith('.py'):
    sys.exit(0)

status = subprocess.run(['uv', 'run', 'ruff', 'check', '--fix', f]).returncode
if '/src/collector/' in f:
    if subprocess.run(['uv', 'run', 'mypy', '--strict', f]).returncode != 0:
        status = 1
sys.exit(status)"

